mutation($name: String, $displayName: String, $cardIds: [String], $spec: TransactionRuleSpecInput) {
    createTransactionRule(name: $name, displayName: $displayName,  cardIds: $cardIds, spec: $spec) {        
        id
        name
        cards {
            id
        }
        createdAt
        createdBy {
            entityID
            type
        }
        spec {
            specType
            ... on AccumulatingOverPeriodRuleSpec {
                period
                amount
                filters {
                    field
                    value
                    operator
                    invert
                }
            }
            ... on DeclineBasedOnFilterRuleSpec {
                filter {
                    field
                    value
                    operator
                    invert 
                }
            }
            ... on StartEndRuleSpec {
                startDate
                endDate
                limitAmount
                filters {
                field
                value
                operator
                invert
                }
            }
            ... on TimeOfDayRuleSpec {
                startTime
                endTime
            }
            ... on WeekDayRuleSpec {
                daysAllowed
            }                        
        }
    }
}

